<?php
require __DIR__.'/clients.php';
$start=$GLOBALS['essentialChecks'];
$db->query("UPDATE {$p}issuers_staff SET can_view=1 WHERE issuer_id=82 AND staff_id=12");
foreach(['create','edit'] as $cap)$db->query("INSERT INTO {$p}issuers_resource_permissions VALUES(82,12,'customers',?)",[$cap]);
foreach(CompanyClientProfile::NATIVE as $key=>$limit)$db->query('ALTER TABLE '.$p.'clients ADD '.$key.' varchar('.$limit.') DEFAULT NULL');
$db->query('ALTER TABLE '.$p.'clients ADD country int NOT NULL DEFAULT 0');
$db->query('CREATE TABLE '.$p.'countries(country_id int PRIMARY KEY,iso2 varchar(2))');$db->query("INSERT INTO {$p}countries VALUES(32,'BR')");
CompanyClientProfileSchema::ensure($db,$p);CompanyClientProfileSchema::ensure($db,$p);
$profile=new CompanyClientProfile($db,$p);
$pf=['company'=>'Pessoa sintética','vat'=>'39053344705','profile'=>['person_type'=>'pf','rg'=>'RG-SINTETICO','address'=>'Rua sintética','address_number'=>'10','address_complement'=>'Sala 2','address_district'=>'Centro','city'=>'Cidade teste','state'=>'SP','zip'=>'01001-000','country_code'=>'BR','phonenumber'=>'11999990000']];
$pfId=$clients->create(41,12,$pf,hash('sha256','new-profile-pf'));
$loaded=$clients->details(41,12,$pfId);essentialCheck($loaded['profile']['rg']==='RG-SINTETICO'&&$loaded['profile']['address_number']==='10','private PF profile persisted and readable by owner');
essentialCheck((int)$db->query('SELECT country FROM '.$p.'clients WHERE userid=?',[$pfId])->row()->country===32,'ISO country maps real native country');
essentialCheck($clients->create(41,12,$pf,hash('sha256','new-profile-pf'))===$pfId,'profile create replay idempotent');
$changed=$pf;$changed['profile']['rg']='OTHER';essentialThrows(fn()=>$clients->create(41,12,$changed,hash('sha256','new-profile-pf')),'company_client_request_conflict','profile included in create receipt');
$clients->setSharing(41,12,$pfId,[82],$loaded['revision']);$shared=$clients->details(82,12,$pfId);
essentialCheck($shared['profile']===[]&&!array_key_exists('rg',$shared['client']),'sharing never shares RG or supplementary profile');
essentialThrows(fn()=>$profile->read(82,12,$pfId),'company_client_access_denied','shared identity cannot read private profile directly');
essentialThrows(fn()=>$profile->write(82,12,$pfId,['rg'=>'FOREIGN']),'company_client_access_denied','shared identity cannot write private profile');
$pj=['company'=>'Empresa sintética','vat'=>'11222333000181','profile'=>['person_type'=>'pj','trade_name'=>'Vitrine sintética','state_registration'=>'ISENTO','address'=>'Outra rua','address_number'=>'20','zip'=>'01001-000']];
$pjId=$clients->create(82,12,$pj);essentialCheck($clients->details(82,12,$pjId)['profile']['state_registration']==='ISENTO','PJ explicit exemption persisted');
$bad=$pj;$bad['profile']['rg']='unexpected';essentialThrows(fn()=>$clients->create(82,12,$bad),'company_client_invalid_input','RG rejected in explicit PJ payload');
$bad=$pf;$bad['profile']['state_registration']='unexpected';essentialThrows(fn()=>$clients->create(41,12,$bad),'company_client_invalid_input','IE rejected in explicit PF payload');
$bad=$pf;$bad['profile']['person_type']='pj';essentialThrows(fn()=>$clients->create(41,12,$bad),'company_client_invalid_input','type and tax must agree');
$before=$clients->details(82,12,$pjId);$db->failOn='INSERT INTO '.$p.'issuers_audit';$edit=$pj;$edit['company']='Changed';$edit['profile']['trade_name']='Rollback';
essentialThrows(fn()=>$clients->update(82,12,$pjId,$edit,$before['revision']),'issuer_storage_failed','audit failure rolls back native row and private profile');$db->failOn=null;
essentialCheck($clients->details(82,12,$pjId)===$before,'exact rollback includes revision and profile');
$edit['company']=$pj['company'];$clients->update(82,12,$pjId,$edit,$before['revision']);
essentialThrows(fn()=>$clients->update(82,12,$pjId,$pj,$before['revision']),'company_client_stale','supplementary profile participates optimistic revision');
$before=$profile->read(82,12,$pjId);$clients->update(82,12,$pjId,['company'=>'API-compatible name','vat'=>$pj['vat']]);
essentialCheck($profile->read(82,12,$pjId)===$before,'old API update without profile preserves extras');
essentialCheck(array_keys($clients->get(82,12,$pjId))===['userid','company','vat','active','owner_issuer_id'],'public identity projection remains unchanged');
$primary=(new IssuerResourceAccess($db,$p))->primaryId();
IssuerTransaction::run($db,$p,CompanyClientProfile::TABLES,fn()=>$profile->write($primary,7,9,['person_type'=>'pf','rg'=>'LEGACY-PRIVATE']));
essentialCheck($profile->read($primary,7,9)['rg']==='LEGACY-PRIVATE','unowned legacy profile belongs to primary issuer');
essentialThrows(fn()=>$profile->read(41,12,9),'company_client_access_denied','legacy private profile not readable by secondary');
essentialThrows(fn()=>$profile->write(41,12,$pfId,['rg'=>'UNOWNED']),'issuer_owned_transaction_required','profile writer requires serialized owned transaction');
essentialThrows(fn()=>IssuerTransaction::run($db,$p,CompanyClientProfile::TABLES,fn()=>$profile->write(82,12,$pfId,['rg'=>'FOREIGN'])),'company_client_access_denied','mismatched issuer/client rejected inside owning lock');
$db->query('INSERT INTO '.$p.'company_client_profiles(issuer_id,client_id,profile_json) VALUES(?,?,?)',[82,$pfId,'{"rg":"INJECTED"}']);
essentialThrows(fn()=>$profile->read(82,12,$pfId),'company_client_access_denied','even mismatched persisted row cannot bypass ownership');
$db->query('DELETE FROM '.$p.'company_client_profiles WHERE issuer_id=? AND client_id=?',[82,$pfId]);
essentialCheck(CompanyClientProfile::normalize(['person_type'=>'pf','rg'=>''],null)===['person_type'=>'pf','rg'=>''],'RG optional without document');
essentialCheck(CompanyClientProfile::normalize(['person_type'=>'pj','state_registration'=>''],null)===['person_type'=>'pj','state_registration'=>''],'IE optional without universal requirement');
// Partial writes must validate the resulting private profile, not just submitted fields.
$beforeTransition=$clients->details(41,12,$pfId);
$transition=['company'=>'Synthetic converted company','vat'=>'98989898000177','profile'=>['person_type'=>'pj']];
essentialThrows(fn()=>$clients->update(41,12,$pfId,$transition,$beforeTransition['revision']),'company_client_invalid_input','partial PF to PJ cannot silently retain an incompatible RG');
essentialCheck($clients->details(41,12,$pfId)===$beforeTransition,'rejected merged profile rolls back native identity and private data');
$transition['profile']['rg']='';
$clients->update(41,12,$pfId,$transition,$beforeTransition['revision']);
$afterTransition=$clients->details(41,12,$pfId);
essentialCheck($afterTransition['profile']['person_type']==='pj'&&$afterTransition['profile']['rg']==='','explicitly cleared incompatible field permits reviewed type transition');
echo 'Customer supplementary profiles: '.($GLOBALS['essentialChecks']-$start).' new checks ('.$db->driver().").\n";
